"""Public child I/O and limits. No candidate is imported into this process."""
import ctypes
import math
import os
from pathlib import Path
import platform
import resource
import selectors
import signal
import subprocess
import sys
import time

DENIED = {'socket': 41, 'socketpair': 53, 'connect': 42, 'shmget': 29, 'shmat': 30, 'shmctl': 31, 'semget': 64, 'semop': 65, 'semctl': 66, 'semtimedop': 220, 'msgget': 68, 'msgsnd': 69, 'msgrcv': 70, 'msgctl': 71, 'kill': 62, 'tkill': 200, 'tgkill': 234, 'ptrace': 101, 'process_vm_readv': 310, 'process_vm_writev': 311, 'unshare': 272, 'setns': 308, 'mount': 165, 'umount2': 166, 'pivot_root': 155, 'chroot': 161, 'setsid': 112, 'setpgid': 109, 'setuid': 105, 'setgid': 106, 'setreuid': 113, 'setregid': 114, 'setresuid': 117, 'setresgid': 119, 'setgroups': 116, 'open_by_handle_at': 304, 'name_to_handle_at': 303, 'bpf': 321, 'keyctl': 250, 'add_key': 248, 'request_key': 249, 'perf_event_open': 298, 'userfaultfd': 323, 'io_uring_setup': 425, 'io_uring_enter': 426, 'io_uring_register': 427, 'fork': 57, 'vfork': 58, 'clone': 56, 'pidfd_getfd': 438}


def child_limits():
    if os.geteuid() == 0:
        raise RuntimeError("candidate child must be nonroot")
    os.umask(0o077)
    for key, limits in (
        (resource.RLIMIT_AS, (4*1024**3, 4*1024**3)),
        (resource.RLIMIT_CPU, (360, 361)),
        (resource.RLIMIT_FSIZE, (64*1024**2, 64*1024**2)),
        (resource.RLIMIT_NOFILE, (64, 64)),
        (resource.RLIMIT_NPROC, (1, 1)),
        (resource.RLIMIT_CORE, (0, 0))):
        resource.setrlimit(key, limits)
    if platform.machine() != 'x86_64':
        raise RuntimeError("x86-64 required")
    class Filter(ctypes.Structure):
        _fields_ = [('code',ctypes.c_ushort),('jt',ctypes.c_ubyte),
                    ('jf',ctypes.c_ubyte),('k',ctypes.c_uint)]
    class Program(ctypes.Structure):
        _fields_ = [('length',ctypes.c_ushort),('filters',ctypes.POINTER(Filter))]
    # load arch; kill wrong arch; load nr; kill x32; errno for selected calls.
    code = [(0x20,0,0,4),(0x15,1,0,0xc000003e),(0x06,0,0,0x80000000),
            (0x20,0,0,0),(0x35,0,1,0x40000000),(0x06,0,0,0x80000000)]
    for number in DENIED.values():
        code += [(0x15,0,1,number),(0x06,0,0,0x50000 | 1)]
    code += [(0x15,0,1,435),(0x06,0,0,0x50000 | 38),(0x06,0,0,0x7fff0000)]
    filters = (Filter * len(code))(*(Filter(*row) for row in code))
    program = Program(len(code), filters)
    libc = ctypes.CDLL(None, use_errno=True)
    if libc.prctl(38,1,0,0,0) or libc.prctl(22,2,ctypes.byref(program),0,0):
        raise OSError(ctypes.get_errno(), 'seccomp installation failed')


class CandidateFailure(Exception):
    pass


def execute(path, data, scratch, wall=450, stdout_cap=128*1024**2, stderr_cap=1024**2):
    env = {'PATH':'/usr/local/bin:/usr/bin:/bin','HOME':'/workspace',
           'LANG':'C','LC_ALL':'C','TMPDIR':str(scratch),
           'PYTHONHASHSEED':'0','PYTHONUNBUFFERED':'1',
           'PYTHONDONTWRITEBYTECODE':'1','OPENBLAS_NUM_THREADS':'1',
           'OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1'}
    started = time.monotonic()
    p = subprocess.Popen([sys.executable,'-I','-B',str(path)], cwd=scratch,
                         stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                         stderr=subprocess.PIPE, env=env, close_fds=True,
                         preexec_fn=child_limits)
    sel = selectors.DefaultSelector()
    capture = [bytearray(), bytearray()]
    streams = [p.stdin, p.stdout, p.stderr]
    offset = 0
    try:
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        if data:
            sel.register(p.stdin, selectors.EVENT_WRITE, -1)
        else:
            p.stdin.close()
        sel.register(p.stdout, selectors.EVENT_READ, 0)
        sel.register(p.stderr, selectors.EVENT_READ, 1)
        deadline = started + wall
        while sel.get_map():
            left = deadline-time.monotonic()
            if left <= 0:
                raise CandidateFailure('wall limit exceeded')
            for key,_ in sel.select(min(.1,left)):
                stream,index = key.fileobj,key.data
                if index == -1:
                    try:
                        n = os.write(stream.fileno(), memoryview(data)[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        sel.unregister(stream);stream.close();continue
                    offset += n
                    if offset == len(data):
                        sel.unregister(stream);stream.close()
                else:
                    limit = (stdout_cap,stderr_cap)[index]
                    try:
                        chunk = os.read(stream.fileno(), min(65536,limit-len(capture[index])+1))
                    except BlockingIOError:
                        continue
                    if not chunk:
                        sel.unregister(stream);stream.close()
                    elif len(capture[index])+len(chunk)>limit:
                        raise CandidateFailure(('stdout','stderr')[index]+' byte limit exceeded')
                    else:
                        capture[index].extend(chunk)
        try:
            code = p.wait(timeout=max(.001,deadline-time.monotonic()))
        except subprocess.TimeoutExpired:
            raise CandidateFailure('wall limit exceeded') from None
        if code:
            raise CandidateFailure('nonzero candidate exit: '+str(code))
        return bytes(capture[0]), bytes(capture[1]), time.monotonic()-started
    finally:
        # The child cannot fork or change UID; only our known child PID is killed.
        old = {}
        for signum in (signal.SIGINT,signal.SIGTERM):
            old[signum] = signal.signal(signum, signal.SIG_IGN)
        try:
            if p.poll() is None:
                p.kill()
            p.wait(timeout=5)
        finally:
            sel.close()
            for stream in streams:
                stream.close()
            for signum,handler in old.items():
                signal.signal(signum,handler)
