"""Validate a public sanity result without constructing candidate-owned trees."""
import json
import re

SPACE=re.compile(rb'[ \t\r\n]*')
SPECIAL=re.compile(rb'["\\\x00-\x1f]')
INTEGER=re.compile(rb'-?(?:0|[1-9][0-9]*)')
DELIMITERS=b' \t\r\n,]}'


def check_result(data,expected):
    """Compare to the trusted public fixture, accepting JSON key/escape variants.

    Storage and recursion depend on expected, never candidate nesting or node
    count. Early mismatch is rejection; no additional task/output bound is added.
    """
    at=0
    size=len(data)

    def space():
        nonlocal at
        at=SPACE.match(data,at).end()

    def take(byte):
        nonlocal at
        space()
        if at>=size or data[at]!=byte:raise ValueError('invalid result shape or JSON')
        at+=1

    def string(maximum):
        nonlocal at
        space()
        if at>=size or data[at]!=34:raise ValueError('JSON string required')
        start=at
        cursor=at+1
        # Every character of a matching ASCII public field needs at most six
        # JSON bytes. This bounds only mismatch detection, not valid answers.
        end=min(size,start+6*maximum+2)
        while cursor<end:
            found=SPECIAL.search(data,cursor,end)
            if found is None:break
            index=found.start();byte=data[index]
            if byte==34:
                token=data[start:index+1].decode('utf-8')
                value=json.loads(token)
                if len(value)>maximum:raise ValueError('wrong result string')
                at=index+1
                return value
            if byte<32:raise ValueError('invalid JSON string')
            cursor=index+2
        raise ValueError('wrong or unterminated result string')

    def value(want):
        nonlocal at
        space()
        kind=type(want)
        if kind is dict:
            take(123)
            seen=set()
            space()
            if at<size and data[at]==125:
                at+=1
                if want:raise ValueError('missing result fields')
                return
            while True:
                key=string(max(map(len,want),default=0))
                if key in seen:raise ValueError('duplicate JSON key')
                if key not in want:raise ValueError('unexpected result field')
                seen.add(key);take(58);value(want[key]);space()
                if at<size and data[at]==125:
                    at+=1
                    if len(seen)!=len(want):raise ValueError('missing result fields')
                    return
                take(44)
        elif kind is list:
            take(91)
            for index,item in enumerate(want):
                if index:take(44)
                value(item)
            take(93)
        elif kind is str:
            if not want.isascii():raise RuntimeError('public fixture string must be ASCII')
            if string(len(want))!=want:raise ValueError('wrong result string')
        elif kind is bool or want is None:
            token=b'null' if want is None else b'true' if want else b'false'
            if not data.startswith(token,at):raise ValueError('wrong JSON literal')
            at+=len(token)
        elif kind is int:
            limit=at+len(str(abs(want)))+2
            number=INTEGER.match(data,at,min(size,limit))
            if number is None:raise ValueError('nonfinite or noninteger result number')
            stop=number.end()
            if stop<size and data[stop] not in DELIMITERS:
                raise ValueError('nonfinite, noninteger or wrong result number')
            if int(number.group())!=want:raise ValueError('wrong result integer')
            at=stop
        else:raise RuntimeError('unsupported trusted public fixture type')

    value(expected)
    space()
    if at!=size:raise ValueError('trailing result data')
